# replaces its stub in place, and the generator never touches it again.

"""The module and item names of a wasm import."""
@parity "dart2wasm/lib/util.dart:87 ImportName" struct ImportName
    module_name::String
    item_name::String
    # the struct's one constructor, tagged; dart's constructor at :91 is its outer function
    ImportName(::Val{:_}, module_name::String, item_name::String) = new(module_name, item_name)
end

# dart reads whether the VM runs its asserts; every dart assert a port reaches is a located rejection
# (src/julia/reject.jl), checked in every run, so a port's asserts are always enabled
@parity "dart2wasm/lib/util.dart:21 compilerAssertsEnabled" compiler_asserts_enabled()::Bool = true

# whether `node` carries the pragma `name`, Julia's declaration standing for it (getPragma); coreTypes is
# dropped (the Kernel table's CoreTypes row)
@parity "dart2wasm/lib/util.dart:27 hasPragma" has_pragma(node::Union{Core.MethodInstance,ClassField,GlobalRef,DataType,Module}, name::String)::Bool =
    get_pragma(node, name; default_value = "") !== nothing

# the value of the pragma `name` on `node`: dart's annotation, Julia's declaration standing for it, or
# nothing where `node` has none (the Kernel table's Annotatable row: a field, a binding, a class or a
# module declares none). On a method: `@inline` is wasm:prefer-inline and `@noinline`
# wasm:never-inline, each valueless, so a declared one answers `default_value` as dart's valueless
# pragma does; wasm:export is the name Julia records for an export (program_export_name: a @ccallable's
# C name or its function's, or the entry's function's name, dart's main), a name `default_value` stands
# for where dart's pragma has none; and wasm:pure-function is Julia's proof that the method is
# removable if unused (its CodeInstance's interprocedural effects), answering `default_value`. The two
# Julia records sit in the closed world, Julia's own keyword `component`. No method is a wasm:import (a
# foreign call is a host import, dev/MARCH.md 1.F), a wasm:weak-export (Julia's exports are all strong)
# or a wasm:entry-point (the runtime's roots are RUNTIME_ENTRY_POINTS, src/julia/subset.jl), and no
# other pragma has a Julia declaration. coreTypes is dropped (the CoreTypes row)
@parity "dart2wasm/lib/util.dart:31 getPragma" function get_pragma(node::Union{Core.MethodInstance,ClassField,GlobalRef,DataType,Module}, name::String; default_value::Union{String,Bool,Nothing} = nothing,
        component::Union{NirWorld,Nothing} = nothing)::Union{String,Bool,Nothing}
    node isa Core.MethodInstance || return nothing
    local method = node.def::Method
    name == "wasm:prefer-inline" && return Core.Compiler.is_declared_inline(method) ? default_value : nothing
    name == "wasm:never-inline" && return Core.Compiler.is_declared_noinline(method) ? default_value : nothing
    if name == "wasm:export" || name == "wasm:pure-function"
        component === nothing && reject!(Internal("dart2wasm/lib/util.dart:31 getPragma: $name of $node, which Julia records in the closed world, asked with none"), "get_pragma")
        name == "wasm:export" && return program_export_name(node, component.entry)
        return Core.Compiler.is_removable_if_unused(Core.Compiler.decode_effects(nir_body_of(component, node).ci.ipo_purity_bits)) ? default_value : nothing
    end
    return nothing
end

# dart's `wasm:import` pragma: no Julia method is an import, a foreign call being a host import
# (dev/MARCH.md 1.F); coreTypes, Kernel's (the Kernel table's CoreTypes row), is dropped
@parity "dart2wasm/lib/util.dart:68 hasWasmImportPragma" has_wasm_import_pragma(member::Core.MethodInstance)::Bool = get_wasm_import_pragma(member) !== nothing

# dart parses the pragma's value into an ImportName; getPragma answers none for every Julia method
@parity "dart2wasm/lib/util.dart:72 getWasmImportPragma" get_wasm_import_pragma(member::Core.MethodInstance)::Nothing =
    get_pragma(member, "wasm:import")

@parity "dart2wasm/lib/util.dart:91 ImportName" ImportName(module_name::String, item_name::String)::ImportName = ImportName(Val(:_), module_name, item_name)

# dart's toString; Julia's show writes to the stream it is given
@parity "dart2wasm/lib/util.dart:94 ImportName.toString" Base.show(io::IO, self::ImportName)::Nothing = print(io, self.module_name, '.', self.item_name)

# dart's `wasm:export` pragma, Julia's `Base.@ccallable` and the program's entry (get_wasm_export_pragma)
@parity "dart2wasm/lib/util.dart:99 hasWasmExportPragma" has_wasm_export_pragma(member::Core.MethodInstance; component::NirWorld)::Bool = get_wasm_export_pragma(member; component = component) !== nothing

# dart's `wasm:weak-export` pragma: Julia has no weak export, every export being strong
@parity "dart2wasm/lib/util.dart:103 hasWasmWeakExportPragma" has_wasm_weak_export_pragma(member::Core.MethodInstance)::Bool = get_wasm_weak_export_pragma(member) !== nothing

# dart's `wasm:prefer-inline` pragma, Julia's `@inline` declaration (getPragma): true when declared, else none
@parity "dart2wasm/lib/util.dart:107 getWasmPreferInlinePragma" get_wasm_prefer_inline_pragma(member::Core.MethodInstance)::Union{Bool,Nothing} =
    get_pragma(member, "wasm:prefer-inline"; default_value = true)

# dart's `wasm:never-inline` pragma, Julia's `@noinline` declaration (getPragma): true when declared, else none
@parity "dart2wasm/lib/util.dart:116 getWasmNeverInlinePragma" get_wasm_never_inline_pragma(member::Core.MethodInstance)::Union{Bool,Nothing} =
    get_pragma(member, "wasm:never-inline"; default_value = true)

# dart's `wasm:export` pragma, its value or the member's name: a `Base.@ccallable` method's, the C
# name @ccallable records, else its function's name; the program's entry, its function's name, as
# dart's runtime exports its main invoker; no other member (program_export_name, src/julia/subset.jl,
# the one statement of the rule). coreTypes is dropped (the Kernel table's CoreTypes row), and the closed
# world, whose entry it names, is Julia's own keyword
@parity "dart2wasm/lib/util.dart:125 getWasmExportPragma" get_wasm_export_pragma(member::Core.MethodInstance; component::NirWorld)::Union{String,Nothing} =
    get_pragma(member, "wasm:export"; default_value = string((member.def::Method).name), component = component)

@parity "dart2wasm/lib/util.dart:134 getWasmWeakExportPragma" get_wasm_weak_export_pragma(member::Core.MethodInstance)::Nothing =
    get_pragma(member, "wasm:weak-export"; default_value = string((member.def::Method).name))

# dart's `wasm:pure-function` pragma, which dart2wasm gives wasm-opt as binaryen.removable.if.unused:
# Julia proves it of a method, its CodeInstance's interprocedural effects removable if unused (effect
# free, nothrow and terminating; Base.@assume_effects declares the same), Julia's own judgement of the
# body the closed world compiles. coreTypes is dropped (the Kernel table's CoreTypes row), and the
# closed world, whose CodeInstance it reads, is Julia's own keyword
@parity "dart2wasm/lib/util.dart:143 hasWasmPureFunctionPragma" has_wasm_pure_function_pragma(member::Core.MethodInstance; component::NirWorld)::Bool =
    get_pragma(member, "wasm:pure-function"; default_value = true, component = component) == true

# dart adds an annotation to a Kernel node in its transforms; a Julia method's declarations are fixed
# by its source, and a runtime root is kept by RUNTIME_ENTRY_POINTS (src/julia/subset.jl), so no
# transform adds one. coreTypes is dropped (the CoreTypes row)
@parity "dart2wasm/lib/util.dart:154 addWasmEntryPointPragma" add_wasm_entry_point_pragma(node::Union{Core.MethodInstance,ClassField,GlobalRef,DataType,Module})::Union{} =
    reject!(Internal("dart2wasm/lib/util.dart:154 addWasmEntryPointPragma: an entry-point pragma added to $node; a Julia method's declarations are its source's, a runtime root kept by RUNTIME_ENTRY_POINTS"), "add_wasm_entry_point_pragma")

@parity "dart2wasm/lib/util.dart:157 addPragma" add_pragma(node::Union{Core.MethodInstance,ClassField,GlobalRef,DataType,Module}, pragma_name::String; value::Union{Nothing,Union{NirConst,Dart2Wasm.DummyValueConstant}} = nothing)::Union{} =
    reject!(Internal("dart2wasm/lib/util.dart:157 addPragma: the pragma $pragma_name added to $node; a Julia method's declarations are its source's, which no transform adds to"), "add_pragma")

# dart's `>>>=` is the unsigned shift, Julia's `>>>`
@parity "dart2wasm/lib/util.dart:172 _intToLittleEndianBytes" function _int_to_little_endian_bytes(i::Int64)::Vector{UInt8}
    local bytes = UInt8[]
    push!(bytes, (i & 0xFF) % UInt8)
    i >>>= 8
    while i != 0
        push!(bytes, (i & 0xFF) % UInt8)
        i >>>= 8
    end
    return bytes
end

# dart:convert's `base64.encode`, RFC 4648's standard alphabet with `=` padding, written here: Julia's
# Base64 is a standard library WasmTarget does not depend on
@parity "dart2wasm/lib/util.dart:183 intToBase64" function int_to_base64(i::Int64)::String
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local bytes = _int_to_little_endian_bytes(i)
    local out = IOBuffer()
    for k in 1:3:length(bytes)
        local n = min(3, length(bytes) - k + 1)
        local w = UInt32(bytes[k]) << 16 | (n > 1 ? UInt32(bytes[k+1]) << 8 : 0x0) | (n > 2 ? UInt32(bytes[k+2]) : 0x0)
        for j in 0:3
            write(out, j <= n ? alphabet[((w >> (18 - 6j)) & 0x3f) + 1] : '=')
        end
    end
    return String(take!(out))
end

"""The name of the module with the given `id`, in its name section and in imports."""
@parity "dart2wasm/lib/util.dart:199 moduleNameFromId" module_name_from_id(id::Int64)::String = id == 0 ? "M" : "M$id"

"""The reverse of `module_name_from_id`; `nothing` for a name it does not make, dart's `int?`."""
@parity "dart2wasm/lib/util.dart:202 moduleNameToId" function module_name_to_id(module_name::String)::Union{Int64,Nothing}
    module_name == "M" && return 0
    # dart's int.tryParse: an optional sign, then decimal digits or 0x and hexadecimal ones, else null
    if startswith(module_name, "M")
        local digits = module_name[2:end]
        local m = match(r"^\s*([+-]?)0[xX]([0-9a-fA-F]+)\s*$", digits)
        m === nothing || return tryparse(Int64, m[1] * m[2]; base = 16)
        return tryparse(Int64, digits; base = 10)
    end
    return nothing
end

"""Maps ints to minimal length strings of the 92 printable characters from 35 to 126; never empty."""
@parity "dart2wasm/lib/util.dart:216 intToMinString" function int_to_min_string(i::Int64)::String
    # Stick to the 92 printable characters (starting after "), from 35 to 126.
    local base = 92
    i >= 0 || reject!(Internal("dart2wasm/lib/util.dart:216 intToMinString: the negative $i"), "intToMinString")
    i += 1
    local code_units = Char[]
    while i > 0
        local remainder = i % base
        i ÷= base
        push!(code_units, Char(remainder + 35))
    end
    return String(code_units)
end

"""Maps ints to minimal length strings safe as JavaScript identifiers, of A-Z and a-z; never empty."""
@parity "dart2wasm/lib/util.dart:234 intToMinJsSafeString" function int_to_min_js_safe_string(i::Int64)::String
    i >= 0 || reject!(Internal("dart2wasm/lib/util.dart:234 intToMinJsSafeString: the negative $i"), "intToMinJsSafeString")
    i += 1
    local code_units = Char[]
    while i > 0
        local remainder = i % 52
        i ÷= 52
        if remainder < 26
            push!(code_units, Char(remainder + 65))        # 'A'-'Z'
        else
            push!(code_units, Char(remainder - 26 + 97))   # 'a'-'z'
        end
    end
    return String(code_units)
end

# dart's empty Kernel component with TFA's metadata repositories, which a codegen phase reads a .dill into;
# Julia's program is the closed world build_nir alone makes, its inference results the metadata (the
# Kernel table's Component and MetadataRepository rows)
@parity "dart2wasm/lib/util.dart:250 createEmptyComponent" create_empty_component()::Union{} =
    reject!(Internal("dart2wasm/lib/util.dart:250 createEmptyComponent: a Kernel component read from a .dill; Julia's program is the closed world build_nir makes, its inference results the metadata (the Kernel table's Component row)"), "create_empty_component")
